"""Small BGR-to-ROS adapter kept local to the disposable test package."""

import numpy as np
from sensor_msgs.msg import Image


def bgr8_message(frame: np.ndarray, header) -> Image:
    image = np.ascontiguousarray(frame, dtype=np.uint8)
    if image.ndim != 3 or image.shape[2] != 3:
        raise ValueError("BGR input must have shape (height, width, 3)")
    message = Image()
    message.header = header
    message.height, message.width = map(int, image.shape[:2])
    message.encoding = "bgr8"
    message.is_bigendian = False
    message.step = message.width * 3
    message.data = image.tobytes()
    return message
